/* @lc app=leetcode id=1864 lang=kotlin */ class Solution { fun minSwaps(s: String): Int = s.count { it == '1' }.let { ones -> (s.length - ones).let { zeros -> if (kotlin.math.abs(ones - zeros) > 1) -1 else s.indices.count { s[it] != if (it % 2 == 0) '1' else '0' }.let { m1 -> s.indices.count { s[it] != if (it % 2 == 0) '0' else '1' }.let { m0 -> if (ones > zeros) m1 / 2 else if (zeros > ones) m0 / 2 else minOf(m1, m0) / 2 } } } } }